import { createClient } from '@supabase/supabase-js'
import { randomBytes } from 'crypto'
import { NextRequest, NextResponse } from 'next/server'
import { isAdminRequest } from '@/lib/admin-session'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i

// Friendly alphabet: no 0/O, no 1/I/L — easy to read aloud over the phone.
const CODE_ALPHABET = 'REDACTED'

function generateActivationCode(): string {
  const bytes = randomBytes(8)
  let out = ''
  for (let i = 0; i < 8; i++) out += CODE_ALPHABET[bytes[i] % CODE_ALPHABET.length]
  return `YFF-${out}`
}

export async function POST(req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  if (!isAdminRequest(req)) return NextResponse.json({ error: 'Admin login required.' }, { status: 401 })

  const { id } = await params
  if (!UUID_RE.test(id)) return NextResponse.json({ error: 'Invalid rider id.' }, { status: 400 })

  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )

  const { data: rider } = await supabase
    .from('delivery_boys')
    .select('id, status, activation_code')
    .eq('id', id)
    .maybeSingle()

  if (!rider) return NextResponse.json({ error: 'Rider not found.' }, { status: 404 })
  if (rider.status === 'active') {
    return NextResponse.json({ error: 'Rider is already active.' }, { status: 409 })
  }
  if (rider.status === 'suspended') {
    return NextResponse.json({ error: 'Rider is suspended. Reinstate first.' }, { status: 409 })
  }

  // If a prior approval issued a code that hasn't been consumed, reuse it
  // so the admin doesn't have to call the rider again with a new one.
  const code = rider.activation_code || generateActivationCode()

  const { error: updErr } = await supabase
    .from('delivery_boys')
    .update({
      status: 'approved',
      activation_code: code,
      approved_at: new Date().toISOString(),
    })
    .eq('id', id)

  if (updErr) {
    console.error('[YFF admin/approve] update failed:', updErr.message)
    return NextResponse.json({ error: updErr.message }, { status: 500 })
  }

  return NextResponse.json({ ok: true, activation_code: code })
}

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { hashPassword } from '@/lib/password'
import { normalizePhone } from '@/lib/phone'
import { rateLimit } from '@/lib/rate-limit'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

const ALLOWED_TYPES = new Set(['image/jpeg', 'image/jpg', 'image/png', 'image/webp'])
const MAX_BYTES = 8 * 1024 * 1024 // 8MB — ID photos are usually a single page
const VEHICLE_TYPES = new Set(['bike', 'scooter', 'cycle', 'auto', 'other'])

function bad(msg: string, status = 400) {
  return NextResponse.json({ error: msg }, { status })
}

export async function POST(req: NextRequest) {
  const ip = req.headers.get('x-forwarded-for')?.split(',')[0]?.trim() || 'unknown'
  if (!rateLimit(`rider-reg:${ip}`, 5, 60 * 60 * 1000)) {
    return NextResponse.json(
      { error: 'Too many sign-up attempts. Try again in an hour.' },
      { status: 429 },
    )
  }

  let form: FormData
  try {
    form = await req.formData()
  } catch {
    return bad('Invalid upload payload.')
  }

  const name = String(form.get('name') ?? '').trim().slice(0, 80)
  const phone = normalizePhone(form.get('phone') as string | null)
  const altPhone = normalizePhone(form.get('alt_phone') as string | null)
  const password = String(form.get('password') ?? '')
  const vehicleType = String(form.get('vehicle_type') ?? '').trim().toLowerCase()
  const vehicleNumber = String(form.get('vehicle_number') ?? '').trim().toUpperCase().slice(0, 20)
  const serviceAreas = String(form.get('service_areas') ?? '').trim().slice(0, 400)
  const file = form.get('file')

  if (!name) return bad('Please enter your name.')
  if (!phone) return bad('Enter a valid 10-digit phone number.')
  if (password.length < 6) return bad('Password must be at least 6 characters.')
  if (password.length > 128) return bad('Password is too long.')
  if (!VEHICLE_TYPES.has(vehicleType)) return bad('Pick a vehicle type.')
  if (!vehicleNumber) return bad('Enter your vehicle number.')
  if (!serviceAreas) return bad('Enter the areas you can deliver to.')
  if (!(file instanceof File)) return bad('Attach a photo of your ID proof.')
  if (!ALLOWED_TYPES.has(file.type)) return bad('Only JPG, PNG, or WEBP images are allowed.')
  if (file.size === 0) return bad('ID photo is empty.')
  if (file.size > MAX_BYTES) return bad('ID photo is too large. Max 8MB.')

  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )

  console.log('[YFF rider-register] attempt phone=%s name=%s', phone, name)

  const { data: existing, error: lookupErr } = await supabase
    .from('delivery_boys')
    .select('id, status')
    .eq('phone', phone)
    .maybeSingle()

  if (lookupErr) {
    console.error('[YFF rider-register] lookup failed:', lookupErr.code, lookupErr.message)
    if (lookupErr.message?.includes('does not exist') || lookupErr.code === '42P01') {
      return bad('delivery_boys table is missing. Run scripts/delivery-feature-migration.sql first.', 500)
    }
    return bad(`Database error: ${lookupErr.message}`, 500)
  }
  if (existing) {
    return bad('An application already exists for this phone. Use the same number to log in once activated.', 409)
  }

  const ext = file.type === 'image/png' ? 'png' : file.type === 'image/webp' ? 'webp' : 'jpg'
  const path = `${phone}-${Date.now()}.${ext}`

  const { error: upErr } = await supabase.storage
    .from('rider-id-proofs')
    .upload(path, file, { contentType: file.type, upsert: false })

  if (upErr) {
    console.error('[YFF rider-register] id-proof upload failed:', upErr.message)
    return bad('Could not save ID photo. Please try again.', 500)
  }

  const password_hash = hashPassword(password)
  const { data: created, error: insertErr } = await supabase
    .from('delivery_boys')
    .insert({
      name,
      phone,
      alt_phone: altPhone || null,
      password_hash,
      vehicle_type: vehicleType,
      vehicle_number: vehicleNumber,
      id_proof_path: path,
      service_areas: serviceAreas,
      status: 'pending_approval',
    })
    .select('id')
    .single()

  if (insertErr || !created) {
    console.error('[YFF rider-register] insert failed:', insertErr?.code, insertErr?.message)
    // Best-effort: drop the just-uploaded photo so we don't leak orphan storage objects
    await supabase.storage.from('rider-id-proofs').remove([path]).catch(() => null)
    return bad(insertErr?.message || 'Could not save your application. Please try again.', 500)
  }

  console.log('[YFF rider-register] success id=%s', created.id)
  return NextResponse.json({ ok: true, status: 'pending_approval' })
}

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { verifyPassword } from '@/lib/password'
import { normalizePhone } from '@/lib/phone'
import { setRiderSessionCookie } from '@/lib/rider-session'
import { rateLimit } from '@/lib/rate-limit'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

function bad(msg: string, status = 400) {
  return NextResponse.json({ error: msg }, { status })
}

export async function POST(req: NextRequest) {
  const body = await req.json().catch(() => null)
  if (!body || typeof body !== 'object') return bad('Invalid request.')

  const phone = normalizePhone(body.phone)
  const password = String(body.password ?? '')

  if (!phone) return bad('Enter a valid 10-digit phone number.')
  if (!password) return bad('Enter your password.')

  const ip = req.headers.get('x-forwarded-for')?.split(',')[0]?.trim() || 'unknown'
  if (
    !rateLimit(`rider-login:phone:${phone}`, 5, 10 * 60 * 1000) ||
    !rateLimit(`rider-login:ip:${ip}`, 30, 10 * 60 * 1000)
  ) {
    return bad('Too many login attempts. Please try again in a few minutes.', 429)
  }

  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )

  const { data: rider, error } = await supabase
    .from('delivery_boys')
    .select('id, name, phone, status, password_hash')
    .eq('phone', phone)
    .maybeSingle()

  if (error) {
    console.error('[YFF rider-login] lookup failed:', error.code, error.message)
    if (error.message?.includes('does not exist') || error.code === '42P01') {
      return bad('delivery_boys table is missing. Run scripts/delivery-feature-migration.sql first.', 500)
    }
    return bad(`Database error: ${error.message}`, 500)
  }
  if (!rider) return bad('No rider account for this number. Sign up first.', 404)

  if (!rider.password_hash || !verifyPassword(password, rider.password_hash)) {
    return bad('Wrong password.', 401)
  }

  // Lifecycle gate — only fully activated accounts can hold a session.
  if (rider.status === 'pending_approval') {
    return bad('Your application is waiting for owner approval.', 403)
  }
  if (rider.status === 'approved') {
    return bad('Your account is approved. Please activate it with the code from the owner first.', 403)
  }
  if (rider.status === 'suspended') {
    return bad('Your account is suspended. Contact the owner.', 403)
  }
  if (rider.status !== 'active') {
    return bad('Your account is not active.', 403)
  }

  await supabase
    .from('delivery_boys')
    .update({ last_login_at: new Date().toISOString() })
    .eq('id', rider.id)

  console.log('[YFF rider-login] success id=%s', rider.id)

  const res = NextResponse.json({
    ok: true,
    rider: { id: rider.id, name: rider.name, phone: rider.phone },
  })
  try {
    setRiderSessionCookie(res, rider.id)
  } catch (e) {
    const msg = e instanceof Error ? e.message : 'Session setup failed.'
    return bad(msg, 500)
  }
  return res
}

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { getRiderSessionFromRequest } from '@/lib/rider-session'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

type DeliveryStatus = 'unassigned' | 'assigned' | 'picked_up' | 'out_for_delivery' | 'delivered'

type OrderRow = {
  id: string
  farmer_id: string
  produce_name: string | null
  quantity: number | null
  unit: string | null
  total_price: number | null
  buyer_name: string | null
  buyer_phone: string | null
  payment_method: string | null
  payment_status: string | null
  delivery_status: DeliveryStatus | null
  delivery_address: string | null
  delivery_landmark: string | null
  delivery_pincode: string | null
  delivery_alt_phone: string | null
  delivery_boy_id: string | null
  assigned_at: string | null
  picked_up_at: string | null
  out_for_delivery_at: string | null
  created_at: string
}

type Farmer = { id: string; name: string; village: string; phone: string | null }

export async function GET(req: NextRequest) {
  const session = getRiderSessionFromRequest(req)
  if (!session) return NextResponse.json({ error: 'Not logged in.' }, { status: 401 })

  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )

  // Gate: only active riders see orders. Suspended/pending accounts are kicked
  // out of /api/rider/me as well, but we double-check here to be safe.
  const { data: rider } = await supabase
    .from('delivery_boys')
    .select('id, status')
    .eq('id', session.riderId)
    .maybeSingle()

  if (!rider || rider.status !== 'active') {
    return NextResponse.json({ error: 'Account not active.' }, { status: 403 })
  }

  // Available — farmer-approved home deliveries that no rider has taken yet.
  // Mine — anything currently assigned to me and not yet delivered.
  const { data: availableRaw, error: availErr } = await supabase
    .from('orders')
    .select(
      'id, farmer_id, produce_name, quantity, unit, total_price, payment_method, payment_status, delivery_pincode, delivery_status, created_at',
    )
    .eq('delivery_type', 'home_delivery')
    .eq('status', 'approved')
    .is('delivery_boy_id', null)
    .or('delivery_status.is.null,delivery_status.eq.unassigned')
    .order('created_at', { ascending: true })
    .limit(50) as { data: OrderRow[] | null; error: { message: string } | null }

  if (availErr) {
    console.error('[YFF rider/orders] available query failed:', availErr.message)
    return NextResponse.json({ error: 'Could not load orders.' }, { status: 500 })
  }

  const { data: mineRaw, error: mineErr } = await supabase
    .from('orders')
    .select(
      'id, farmer_id, produce_name, quantity, unit, total_price, buyer_name, buyer_phone, payment_method, payment_status, delivery_status, delivery_address, delivery_landmark, delivery_pincode, delivery_alt_phone, delivery_boy_id, assigned_at, picked_up_at, out_for_delivery_at, created_at',
    )
    .eq('delivery_boy_id', session.riderId)
    .in('delivery_status', ['assigned', 'picked_up', 'out_for_delivery'])
    .order('assigned_at', { ascending: true })
    .limit(50) as { data: OrderRow[] | null; error: { message: string } | null }

  if (mineErr) {
    console.error('[YFF rider/orders] mine query failed:', mineErr.message)
    return NextResponse.json({ error: 'Could not load your deliveries.' }, { status: 500 })
  }

  const farmerIds = [...new Set([
    ...(availableRaw ?? []).map((o) => o.farmer_id),
    ...(mineRaw ?? []).map((o) => o.farmer_id),
  ].filter(Boolean))]

  let farmerMap: Record<string, Farmer> = {}
  if (farmerIds.length > 0) {
    const { data: farmers } = await supabase
      .from('farmers')
      .select('id, name, village, phone')
      .in('id', farmerIds)
    farmerMap = Object.fromEntries(
      (farmers ?? []).map((f) => [f.id, { id: f.id, name: f.name, village: f.village, phone: f.phone ?? null }]),
    )
  }

  // Available rows are public to all active riders — withhold consumer name,
  // phone, and street so a rider can't fish for personal info by browsing.
  const available = (availableRaw ?? []).map((o) => {
    const farmer = farmerMap[o.farmer_id] ?? null
    return {
      id: o.id,
      produce_name: o.produce_name,
      quantity: o.quantity,
      unit: o.unit,
      total_price: o.total_price,
      payment_method: o.payment_method,
      payment_status: o.payment_status,
      delivery_pincode: o.delivery_pincode,
      created_at: o.created_at,
      farmer: farmer ? { name: farmer.name, village: farmer.village } : null,
    }
  })

  const mine = (mineRaw ?? []).map((o) => ({
    ...o,
    farmer: farmerMap[o.farmer_id] ?? null,
  }))

  return NextResponse.json({ available, mine })
}

