-- ================================================================
-- YFF Feature Migration
-- Run in: Supabase Dashboard → SQL Editor → New Query → Run
-- ================================================================

-- 1. Harvest date on produce listings
ALTER TABLE produce_listings
  ADD COLUMN IF NOT EXISTS harvest_date date;

-- 2. Cover photo for farmer profile banner
ALTER TABLE farmers
  ADD COLUMN IF NOT EXISTS cover_photo_url text;

-- 3. Farmer avatar/profile photo
ALTER TABLE farmers
  ADD COLUMN IF NOT EXISTS photo_url text;

-- 4. Pesticide test certificate (photo URL)
ALTER TABLE farmers
  ADD COLUMN IF NOT EXISTS pesticide_cert_url text;

-- 5. Pickup schedule: {days: string[], time_from: string, time_to: string}
ALTER TABLE farmers
  ADD COLUMN IF NOT EXISTS pickup_slots jsonb;

-- 6. OTP table for secure farmer login
CREATE TABLE IF NOT EXISTS farmer_otps (
  id          uuid        DEFAULT gen_random_uuid() PRIMARY KEY,
  phone       text        NOT NULL,
  otp         text        NOT NULL,
  expires_at  timestamptz NOT NULL,
  used        boolean     DEFAULT false,
  created_at  timestamptz DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_farmer_otps_phone   ON farmer_otps(phone);
CREATE INDEX IF NOT EXISTS idx_farmer_otps_expires ON farmer_otps(expires_at);

-- RLS: only service-role key (used in API routes) can access
ALTER TABLE farmer_otps ENABLE ROW LEVEL SECURITY;

-- 7. Payment method and status on orders (COD support)
ALTER TABLE orders ADD COLUMN IF NOT EXISTS payment_method text DEFAULT 'cod';
ALTER TABLE orders ADD COLUMN IF NOT EXISTS payment_status text DEFAULT 'pending';

-- 8. Farmer GPS location for distance-based discovery
ALTER TABLE farmers ADD COLUMN IF NOT EXISTS lat numeric(10,7);
ALTER TABLE farmers ADD COLUMN IF NOT EXISTS lng numeric(10,7);
ALTER TABLE farmers ADD COLUMN IF NOT EXISTS location_name text;

-- 9. Password hash for farmer login
ALTER TABLE farmers ADD COLUMN IF NOT EXISTS password_hash text;

-- 10. Farm gallery photos
CREATE TABLE IF NOT EXISTS media (
  id          uuid        DEFAULT gen_random_uuid() PRIMARY KEY,
  farmer_id   uuid        REFERENCES farmers(id) ON DELETE CASCADE,
  type        text        NOT NULL DEFAULT 'photo',
  url         text        NOT NULL,
  caption     text,
  sort_order  integer     DEFAULT 0,
  created_at  timestamptz DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_media_farmer_id ON media(farmer_id);
CREATE INDEX IF NOT EXISTS idx_media_type      ON media(type);

-- 11. Reviewer phone for duplicate-review prevention
ALTER TABLE reviews ADD COLUMN IF NOT EXISTS reviewer_phone text;
CREATE INDEX IF NOT EXISTS idx_reviews_farmer_phone ON reviews(farmer_id, reviewer_phone);

-- 12. WhatsApp click analytics (insert-only, no auth needed)
CREATE TABLE IF NOT EXISTS wa_clicks (
  id         uuid        DEFAULT gen_random_uuid() PRIMARY KEY,
  farmer_id  uuid        REFERENCES farmers(id) ON DELETE SET NULL,
  created_at timestamptz DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_wa_clicks_farmer ON wa_clicks(farmer_id);

-- Allow anonymous inserts for wa_clicks (consumer clicks)
ALTER TABLE wa_clicks ENABLE ROW LEVEL SECURITY;
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE tablename = 'wa_clicks' AND policyname = 'anon insert wa_clicks'
  ) THEN
    EXECUTE 'CREATE POLICY "anon insert wa_clicks" ON wa_clicks FOR INSERT TO anon WITH CHECK (true)';
  END IF;
END $$;

'use client'

import { useCallback, useEffect, useState } from 'react'
import { useRouter } from 'next/navigation'

type Rider = { id: string; name: string | null; phone: string; status: string; vehicle_type: string | null; vehicle_number: string | null }

type AvailableOrder = {
  id: string
  produce_name: string | null
  quantity: number | null
  unit: string | null
  total_price: number | null
  payment_method: string | null
  payment_status: string | null
  delivery_pincode: string | null
  created_at: string
  farmer: { name: string; village: string } | null
}

type DeliveryStatus = 'assigned' | 'picked_up' | 'out_for_delivery'

type MyOrder = {
  id: string
  produce_name: string | null
  quantity: number | null
  unit: string | null
  total_price: number | null
  buyer_name: string | null
  buyer_phone: string | null
  payment_method: string | null
  payment_status: string | null
  delivery_status: DeliveryStatus
  delivery_address: string | null
  delivery_landmark: string | null
  delivery_pincode: string | null
  delivery_alt_phone: string | null
  assigned_at: string | null
  picked_up_at: string | null
  out_for_delivery_at: string | null
  farmer: { id: string; name: string; village: string; phone: string | null } | null
}

export default function RiderDashboardPage() {
  const router = useRouter()
  const [rider, setRider] = useState<Rider | null>(null)
  const [available, setAvailable] = useState<AvailableOrder[]>([])
  const [mine, setMine] = useState<MyOrder[]>([])
  const [tab, setTab] = useState<'available' | 'mine'>('available')
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  const [busyId, setBusyId] = useState<string | null>(null)
  const [otpInputs, setOtpInputs] = useState<Record<string, string>>({})
  const [otpError, setOtpError] = useState<Record<string, string>>({})

  // Pull current rider once. If the cookie is invalid or the account isn't
  // active, /api/rider/me returns rider:null and we kick back to login.
  useEffect(() => {
    let cancelled = false
    fetch('/api/rider/me', { credentials: 'same-origin' })
      .then((r) => r.json())
      .then((json) => {
        if (cancelled) return
        if (!json?.rider) { router.replace('/rider/login'); return }
        setRider(json.rider as Rider)
      })
      .catch(() => { if (!cancelled) router.replace('/rider/login') })
    return () => { cancelled = true }
  }, [router])

  const refresh = useCallback(async () => {
    setError('')
    const r = await fetch('/api/rider/orders', { credentials: 'same-origin' }).catch(() => null)
    if (!r) { setError('Network error. / నెట్‌వర్క్ లోపం'); setLoading(false); return }
    const json = await r.json().catch(() => ({}))
    if (!r.ok) { setError(json?.error ?? 'Could not load orders. / ఆర్డర్‌లు లోడ్ చేయలేకపోయాము'); setLoading(false); return }
    setAvailable((json.available ?? []) as AvailableOrder[])
    setMine((json.mine ?? []) as MyOrder[])
    setLoading(false)
  }, [])

'use client'

import { useCallback, useEffect, useState } from 'react'
import { useRouter } from 'next/navigation'

type Rider = {
  id: string
  name: string | null
  phone: string
  alt_phone: string | null
  vehicle_type: string | null
  vehicle_number: string | null
  service_areas: string | null
  status: 'pending_approval' | 'approved' | 'active' | 'suspended'
  activation_code: string | null
  id_proof_url: string | null
  approved_at: string | null
  activated_at: string | null
  last_login_at: string | null
  created_at: string
}

type DeliveryStatus = 'unassigned' | 'assigned' | 'picked_up' | 'out_for_delivery' | 'delivered'

type DeliveryOrder = {
  id: string
  produce_name: string | null
  quantity: number | null
  unit: string | null
  total_price: number | null
  buyer_name: string | null
  buyer_phone: string | null
  status: 'pending' | 'approved' | 'declined'
  payment_method: string | null
  payment_status: string | null
  delivery_status: DeliveryStatus | null
  delivery_address: string | null
  delivery_landmark: string | null
  delivery_pincode: string | null
  delivery_alt_phone: string | null
  delivery_boy_id: string | null
  handover_otp: string | null
  assigned_at: string | null
  picked_up_at: string | null
  out_for_delivery_at: string | null
  delivered_at: string | null
  created_at: string
  farmer: { id: string; name: string; village: string; phone: string | null } | null
  rider: { id: string; name: string | null; phone: string } | null
}

type ActiveRider = { id: string; name: string | null; phone: string; vehicle_number: string | null }

export default function AdminPage() {
  const router = useRouter()
  const [authed, setAuthed] = useState<boolean | null>(null)
  const [tab, setTab] = useState<'deliveries' | 'riders'>('deliveries')
  const [riders, setRiders] = useState<Rider[]>([])
  const [orders, setOrders] = useState<DeliveryOrder[]>([])
  const [activeRiders, setActiveRiders] = useState<ActiveRider[]>([])
  const [busyId, setBusyId] = useState<string | null>(null)
  const [error, setError] = useState('')
  const [reassignTarget, setReassignTarget] = useState<Record<string, string>>({})
  const [approvalCodes, setApprovalCodes] = useState<Record<string, string>>({})

  useEffect(() => {
    let cancelled = false
    fetch('/api/admin/me', { credentials: 'same-origin' })
      .then((r) => r.json())
      .then((json) => {
        if (cancelled) return
        if (json?.admin) setAuthed(true)
        else router.replace('/admin/login')
      })
      .catch(() => { if (!cancelled) router.replace('/admin/login') })
    return () => { cancelled = true }
  }, [router])

  const loadRiders = useCallback(async () => {
    const r = await fetch('/api/admin/riders', { credentials: 'same-origin' }).catch(() => null)

  onClose: () => void
  onSaved: (updated: Farmer) => void
}) {
  const { tx } = useLang()
  const [name, setName] = useState(farmer.name ?? '')
  const [village, setVillage] = useState(farmer.village ?? '')
  const [district, setDistrict] = useState(farmer.district ?? '')
  const [method, setMethod] = useState(farmer.method ?? 'natural')
  const [sinceYear, setSinceYear] = useState(
    farmer.farming_since_year ? String(farmer.farming_since_year) : '',
  )
  const [pickupLocations, setPickupLocations] = useState<string[]>(
    Array.isArray(farmer.pickup_locations) ? farmer.pickup_locations : [],
  )
  const [newPickup, setNewPickup] = useState('')

  // Cover photo
  const [coverFile, setCoverFile] = useState<File | null>(null)
  const [coverPreview, setCoverPreview] = useState('')
  const [existingCoverUrl, setExistingCoverUrl] = useState(farmer.cover_photo_url ?? '')

  // Avatar photo
  const [avatarFile, setAvatarFile] = useState<File | null>(null)
  const [avatarPreview, setAvatarPreview] = useState('')
  const [existingAvatarUrl, setExistingAvatarUrl] = useState(farmer.photo_url ?? '')

  // Pesticide cert
  const [certFile, setCertFile] = useState<File | null>(null)
  const [certPreview, setCertPreview] = useState('')
  const [existingCertUrl, setExistingCertUrl] = useState(farmer.pesticide_cert_url ?? '')

  // Pickup schedule
  const ALL_DAYS = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday']
  const [slotDays, setSlotDays] = useState<string[]>(farmer.pickup_slots?.days ?? [])
  const [slotFrom, setSlotFrom] = useState(farmer.pickup_slots?.time_from ?? '08:00')
  const [slotTo, setSlotTo]   = useState(farmer.pickup_slots?.time_to   ?? '12:00')

  // UPI ID + QR
  const [upiId, setUpiId] = useState(farmer.upi_id ?? '')
  const [qrFile, setQrFile] = useState<File | null>(null)
  const [qrPreview, setQrPreview] = useState('')
  const [existingQrUrl, setExistingQrUrl] = useState(farmer.upi_qr_code_url ?? '')

  // Cash on Delivery acceptance — default off
  const [codEnabled, setCodEnabled] = useState<boolean>(farmer.cod_enabled === true)

  // Change password
  const [showPwSection, setShowPwSection] = useState(false)
  const [newPassword, setNewPassword]     = useState('')
  const [confirmPassword, setConfirmPassword] = useState('')
  const [pwLoading, setPwLoading]         = useState(false)
  const [pwError, setPwError]             = useState('')
  const [pwSuccess, setPwSuccess]         = useState(false)

  // Farm GPS location
  const [farmerLat, setFarmerLat] = useState<number | null>(farmer.lat ?? null)
  const [farmerLng, setFarmerLng] = useState<number | null>(farmer.lng ?? null)
  const [farmerLocationName, setFarmerLocationName] = useState(farmer.location_name ?? '')
  const [locating, setLocating] = useState(false)
  const [locError, setLocError] = useState('')

  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')

  const handleFarmerGPS = () => {
    if (!navigator.geolocation) {
      setLocError('Geolocation not supported on this device.')
      return
    }
    setLocating(true)
    setLocError('')
    navigator.geolocation.getCurrentPosition(
      (pos) => {
        const { latitude, longitude } = pos.coords
        setFarmerLat(latitude)
        setFarmerLng(longitude)
        // Use village name as display name since we have it
        setFarmerLocationName(farmer.village || 'Farm')
        setLocating(false)
      },
      (err) => {
        setLocError(
          err.code === 1
            ? 'Location permission denied / లొకేషన్ అనుమతి లేదు. Please allow location in browser settings.'
            : 'Could not get location. Please try again. / మళ్ళీ ప్రయత్నించండి.'
        )
        setLocating(false)
      },
      { timeout: 15000, enableHighAccuracy: true },
    )
  }

  const handlePickFile = async (
    e: React.ChangeEvent<HTMLInputElement>,
    setFile: (f: File | null) => void,
    setPreview: (s: string) => void,
    currentPreview: string,
  ) => {
    const file = e.target.files?.[0]
    if (!file) return
    if (!file.type.startsWith('image/')) { setError(tx.pickImageFile); return }
    if (file.size > 8 * 1024 * 1024) { setError(tx.imageTooLarge); return }
    setError('')
    if (currentPreview) URL.revokeObjectURL(currentPreview)
    const compressed = await compressImage(file)
    setFile(compressed)
    setPreview(URL.createObjectURL(compressed))
  }

  const uploadProfileImage = async (file: File, pathSuffix: string): Promise<{ url: string | null; err: string | null }> => {
    const ext = file.name.split('.').pop()?.toLowerCase() || 'jpg'
    // Include timestamp in path so each upload gets a unique URL, busting browser cache
    const path = `${farmer.id}/${pathSuffix}-${Date.now()}.${ext}`
    const { error: upErr } = await supabase.storage
      .from('farm-images')
      .upload(path, file, { contentType: file.type, upsert: false })
    if (upErr) return { url: null, err: `Upload failed: ${upErr.message}` }
    const { data } = supabase.storage.from('farm-images').getPublicUrl(path)
    return { url: data.publicUrl, err: null }
  }

  const toggleDay = (day: string) => {
    setSlotDays((prev) =>
      prev.includes(day) ? prev.filter((d) => d !== day) : [...prev, day],
    )
  }

  const addPickup = () => {
    const v = newPickup.trim()
    if (!v) return
    if (pickupLocations.includes(v)) { setNewPickup(''); return }
    setPickupLocations((prev) => [...prev, v])
    setNewPickup('')
  }
  const removePickup = (loc: string) =>
    setPickupLocations((prev) => prev.filter((l) => l !== loc))

  const handleSave = async () => {
    if (!name.trim()) { setError(tx.nameRequired); return }
    if (!village.trim()) { setError(tx.villageRequired); return }
    if (upiId.trim() && !/^[a-zA-Z0-9._\-]{2,256}@[a-zA-Z]{2,64}$/.test(upiId.trim())) {
      setError('Invalid UPI ID format. Example: yourname@ybl or 9876543210@paytm')
      return
    }
    setLoading(true)
    setError('')

    // Build unique slug from name if current slug is still auto-generated
    const isAutoSlug = /^f-\d{10}-[a-z0-9]{4}$/.test(farmer.slug ?? '')
    const baseSlug = name
      .toLowerCase()
      .trim()
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/(^-|-$)/g, '')
      .slice(0, 40) || 'farmer'
    let newSlug = farmer.slug
    if (isAutoSlug && baseSlug) {
      const rand = Math.random().toString(36).slice(2, 5)
      newSlug = `${baseSlug}-${rand}`
    }

