-- ================================================================
-- YFF — Delivery feature (rider accounts + home delivery on orders)
-- Run in: Supabase Dashboard → SQL Editor → New Query → Run
-- Safe to re-run.
-- ================================================================

-- 1. Delivery boy (rider) accounts. Service-role only; the anon key has no
--    policies on this table.
CREATE TABLE IF NOT EXISTS delivery_boys (
  id              uuid         PRIMARY KEY DEFAULT gen_random_uuid(),
  name            text         NOT NULL,
  phone           varchar(15)  UNIQUE NOT NULL,
  alt_phone       varchar(15),
  password_hash   text         NOT NULL,
  vehicle_type    text,
  vehicle_number  text,
  id_proof_path   text,
  service_areas   text,
  -- Lifecycle: pending_approval → approved (with activation_code issued) →
  -- active (after rider consumes the code). suspended = blocked from logging in.
  status          text         NOT NULL DEFAULT 'pending_approval',
  activation_code text,
  approved_at     timestamptz,
  activated_at    timestamptz,
  last_login_at   timestamptz,
  created_at      timestamptz  DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_delivery_boys_phone   ON delivery_boys(phone);
CREATE INDEX IF NOT EXISTS idx_delivery_boys_status  ON delivery_boys(status);

ALTER TABLE delivery_boys ENABLE ROW LEVEL SECURITY;

COMMENT ON TABLE delivery_boys IS
  'Rider accounts. Service-role only; password scrypt-hashed; activation_code is one-time and cleared once consumed.';

-- 2. Orders — delivery type, address, rider linkage, handover OTP, timestamps.
--    'self_pickup' (default) preserves the existing flow; 'home_delivery'
--    opts in to the new rider workflow.
ALTER TABLE orders ADD COLUMN IF NOT EXISTS delivery_type        text DEFAULT 'self_pickup';
ALTER TABLE orders ADD COLUMN IF NOT EXISTS delivery_status      text;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS delivery_address     text;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS delivery_landmark    text;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS delivery_pincode     text;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS delivery_alt_phone   text;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS delivery_boy_id      uuid REFERENCES delivery_boys(id) ON DELETE SET NULL;
-- 4-digit handover code; generated server-side at order placement for
-- delivery_type='home_delivery'. Never exposed to the rider — they must
-- collect it from the consumer at the door.
ALTER TABLE orders ADD COLUMN IF NOT EXISTS handover_otp         text;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS assigned_at          timestamptz;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS picked_up_at         timestamptz;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS out_for_delivery_at  timestamptz;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS delivered_at         timestamptz;

CREATE INDEX IF NOT EXISTS idx_orders_delivery_status   ON orders(delivery_status);
CREATE INDEX IF NOT EXISTS idx_orders_delivery_boy      ON orders(delivery_boy_id);
CREATE INDEX IF NOT EXISTS idx_orders_delivery_type     ON orders(delivery_type);

-- 3. Private bucket for rider ID proofs. Same pattern as payment-proofs:
--    anon has no policies, only API routes (service role) can upload/sign.
INSERT INTO storage.buckets (id, name, public)
VALUES ('rider-id-proofs', 'rider-id-proofs', false)
ON CONFLICT (id) DO NOTHING;

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { getRiderSessionFromRequest } from '@/lib/rider-session'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i

export async function POST(req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  const { id } = await params
  if (!UUID_RE.test(id)) return NextResponse.json({ error: 'Invalid order id.' }, { status: 400 })

  const session = getRiderSessionFromRequest(req)
  if (!session) return NextResponse.json({ error: 'Not logged in.' }, { status: 401 })

  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )

  const { data: rider } = await supabase
    .from('delivery_boys')
    .select('id, status')
    .eq('id', session.riderId)
    .maybeSingle()
  if (!rider || rider.status !== 'active') {
    return NextResponse.json({ error: 'Account not active.' }, { status: 403 })
  }

  // Optimistic-lock claim — only succeeds if the order is still unclaimed and
  // home-delivery + approved. Two riders tapping Accept simultaneously can't
  // both win because the WHERE clause excludes any row that already has a
  // delivery_boy_id.
  const now = new Date().toISOString()
  const { data: claimed, error } = await supabase
    .from('orders')
    .update({
      delivery_boy_id: session.riderId,
      delivery_status: 'assigned',
      assigned_at: now,
    })
    .eq('id', id)
    .eq('delivery_type', 'home_delivery')
    .eq('status', 'approved')
    .is('delivery_boy_id', null)
    .select('id')

  if (error) {
    console.error('[YFF rider/accept] update failed:', error.message)
    return NextResponse.json({ error: 'Could not accept order.' }, { status: 500 })
  }
  if (!claimed || claimed.length === 0) {
    return NextResponse.json({ error: 'This order was already taken or is no longer available.' }, { status: 409 })
  }

  // Belt-and-braces: if delivery_status was 'unassigned' rather than NULL,
  // the .is() check above wouldn't have filtered it out. We additionally
  // refuse if a prior status was further along the pipeline. (The combination
  // of the IS NULL filter on delivery_boy_id + the status checks above already
  // makes this safe in practice.)

  return NextResponse.json({ ok: true })
}

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { getRiderSessionFromRequest, clearRiderSessionCookie } from '@/lib/rider-session'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

export async function GET(req: NextRequest) {
  const session = getRiderSessionFromRequest(req)
  if (!session) return NextResponse.json({ rider: null }, { status: 200 })

  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )

  const { data: rider } = await supabase
    .from('delivery_boys')
    .select('id, name, phone, status, vehicle_type, vehicle_number')
    .eq('id', session.riderId)
    .maybeSingle()

  // Cookie references a deleted or deactivated account — clear it so the
  // client treats us as logged out.
  if (!rider || rider.status !== 'active') {
    const res = NextResponse.json({ rider: null }, { status: 200 })
    clearRiderSessionCookie(res)
    return res
  }

  return NextResponse.json({ rider })
}

}

// Server-authoritative order placement. Prices, buyer identity, and COD
// permission are computed/checked on the server using the consumer's
// session cookie — never trusted from the cart's client-side state.
const placeOrderViaApi = async (
  group: CartItem[],
  paymentMethod: 'upi' | 'cod',
): Promise<{ ok: true; orderIds: string[]; total: number } | { ok: false; error: string }> => {
  const f = group[0]
  const r = await fetch('/api/orders/place', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    credentials: 'same-origin',
    body: JSON.stringify({
      farmerId: f.farmerId,
      paymentMethod,
      pickupLocation: pickupByFarmer[f.farmerId] || null,
      pickupDay: pickupDayByFarmer[f.farmerId] || null,
      items: group.map((it) => ({ listingId: it.listingId, qty: it.qty })),
      deliveryType,
      deliveryAddress: deliveryType === 'home_delivery' ? deliveryAddress.trim() : null,
      deliveryLandmark: deliveryType === 'home_delivery' ? deliveryLandmark.trim() : null,
      deliveryPincode: deliveryType === 'home_delivery' ? deliveryPincode.trim() : null,
      deliveryAltPhone: deliveryType === 'home_delivery' ? deliveryAltPhone.replace(/\D/g, '').slice(-10) : null,
    }),
  }).catch(() => null)
  if (!r) return { ok: false, error: 'Network error. Please try again.' }
  const json = await r.json().catch(() => ({}))
